[CmdletBinding()]param([string]$Root=(Get-Location).Path)
$ErrorActionPreference='Stop';$base=Join-Path $Root 'ES/Automation/WebPageStudio';$cases=@(
  @{name='network';script='Test-ESWebNetworkRuntimeReceipt.ps1';file='fixtures/network-receipt.valid.json'},
  @{name='preview';script='Test-ESWebPreviewRuntimeReceipt.ps1';file='fixtures/preview-receipt.valid.json'},
  @{name='visual';script='Test-ESWebVisualRegressionReceipt.ps1';file='fixtures/visual-receipt.valid.json'},
  @{name='release';script='Test-ESWebReleaseAcceptanceReceipt.ps1';file='fixtures/release-receipt.valid.json'}
);$out=@();foreach($c in $cases){$p=Join-Path $base $c.file;$args=@{ReceiptPath=$p};if($c.name -eq 'preview'){$args.EnvironmentLockPath=Join-Path $base 'fixtures/browser-environment.lock.valid.json'};$result=& (Join-Path $base $c.script) @args 2>&1;$parsed=$result|Select-Object -Last 1|ConvertFrom-Json;if([string]$parsed.status -ne 'passed'){throw "fixture-failed:$($c.name)"};$out+=$parsed};$negative=@(@{name='network-cancel';script='Test-ESWebNetworkRuntimeReceipt.ps1';file='fixtures/network-receipt.cancel-invalid.json'},@{name='preview-drift';script='Test-ESWebPreviewRuntimeReceipt.ps1';file='fixtures/preview-receipt.drift-invalid.json';lock='fixtures/browser-environment.lock.valid.json'},@{name='visual-diff';script='Test-ESWebVisualRegressionReceipt.ps1';file='fixtures/visual-receipt.diff-invalid.json'},@{name='release-rollback';script='Test-ESWebReleaseAcceptanceReceipt.ps1';file='fixtures/release-receipt.rollback-invalid.json'});$negativeResults=@();foreach($c in $negative){$p=Join-Path $base $c.file;$args=@{ReceiptPath=$p};if($c.lock){$args.EnvironmentLockPath=Join-Path $base $c.lock};$result=& (Join-Path $base $c.script) @args 2>&1;$parsed=$result|Select-Object -Last 1|ConvertFrom-Json;if([string]$parsed.status -ne 'blocked'){throw "negative-fixture-not-blocked:$($c.name)"};$negativeResults+=$parsed};[ordered]@{validator='web-ui-receipt-fixtures';status='passed';positiveCases=$out;negativeCases=$negativeResults;runtimeStatus='runtime-not-run';nonClaims=@('fixtures-are-static','no-network-browser-or-staging-executed')}|ConvertTo-Json -Depth 12
